    private static void RegisterNumber<TNumber>(InspectorEditorRegistry registry, string name)
        where TNumber : struct, INumber<TNumber> => registry.Register<TNumber>(name, static (view, title, read, write, source, propertyName) => view.AddNumber(title, read, write, source, propertyName));
    internal static void RegisterScores<TNumber>(InspectorEditorRegistry registry, string numberName)
        where TNumber : struct, INumber<TNumber>
    {
        registry.Register<LowTieredScore<TNumber>>("LowTieredScore<" + numberName + ">", static (view, title, read, write, source, name) => view.AddNumericValues(title, read, write, new[] { new NumericValueComponent<LowTieredScore<TNumber>, TNumber>("B", static value => value.Bronze, static (value, number) => value.ChangeBronze(number), ""), new NumericValueComponent<LowTieredScore<TNumber>, TNumber>("S", static value => value.Silver, static (value, number) => value.ChangeSilver(number), ""), new NumericValueComponent<LowTieredScore<TNumber>, TNumber>("G", static value => value.Gold, static (value, number) => value.ChangeGold(number), ""), }, source, name));
        registry.Register<HighTieredScore<TNumber>>("HighTieredScore<" + numberName + ">", static (view, title, read, write, source, name) => view.AddNumericValues(title, read, write, new[] { new NumericValueComponent<HighTieredScore<TNumber>, TNumber>("B", static value => value.Bronze, static (value, number) => value.ChangeBronze(number), ""), new NumericValueComponent<HighTieredScore<TNumber>, TNumber>("S", static value => value.Silver, static (value, number) => value.ChangeSilver(number), ""), new NumericValueComponent<HighTieredScore<TNumber>, TNumber>("G", static value => value.Gold, static (value, number) => value.ChangeGold(number), ""), }, source, name));
    }
